async function run() {
  const items = await rss.read({ url: params.feedUrl, max: params.maxItems });

  let seen = state.get('seenLinks') || [];
  const seenSet = new Set(seen);

  const newAgentItems = [];

  for (const item of items) {
    if (!item.link || seenSet.has(item.link)) continue;

    const judgment = await judge.about_agents(item);
    if (judgment.p >= 0.5) {
      newAgentItems.push(item);
    }
    seen.push(item.link);
    seenSet.add(item.link);
  }

  if (seen.length > 300) {
    seen = seen.slice(-300);
  }

  if (newAgentItems.length > 0) {
    const dateStr = dates.format(now(), 'yyyy-MM-dd');
    const lines = newAgentItems
      .map((i) => `- [${i.title}](${i.link})`)
      .join('\n');
    const text = `## ${dateStr}\n${lines}`;
    await obsidian.append({ note: params.nota, text });
    log(`Adicionados ${newAgentItems.length} artigos sobre agentes.`);
  } else {
    log('Nenhum artigo novo sobre agentes encontrado.');
  }

  state.set('seenLinks', seen);
}
